package org.example;

import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
// AI Generated by ChatGPT
public class EvenOddSynchronizationDemo {
    private static final int MAX = 20;

    public static void main(String[] args) throws InterruptedException {
        System.out.println("wait() / notifyAll()");
        MonitorPrinter monitorPrinter = new MonitorPrinter(MAX);
        runThreads(monitorPrinter::printOdd, monitorPrinter::printEven);

        System.out.println("\nReentrantLock / Condition");
        LockPrinter lockPrinter = new LockPrinter(MAX);
        runThreads(lockPrinter::printOdd, lockPrinter::printEven);

        System.out.println("\nSemaphore");
        SemaphorePrinter semaphorePrinter = new SemaphorePrinter(MAX);
        runThreads(semaphorePrinter::printOdd, semaphorePrinter::printEven);
    }

    private static void runThreads(InterruptibleTask oddTask, InterruptibleTask evenTask)
            throws InterruptedException {
        Thread oddThread = new Thread(() -> runTask(oddTask), "odd-thread");
        Thread evenThread = new Thread(() -> runTask(evenTask), "even-thread");
        oddThread.start();
        evenThread.start();
        oddThread.join();
        evenThread.join();
    }

    private static void runTask(InterruptibleTask task) {
        try {
            task.run();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    @FunctionalInterface
    private interface InterruptibleTask {
        void run() throws InterruptedException;
    }

    private static final class MonitorPrinter {
        private final int max;
        private int current = 1;

        private MonitorPrinter(int max) {
            this.max = max;
        }

        private synchronized void printOdd() throws InterruptedException {
            printNumbers(true);
        }

        private synchronized void printEven() throws InterruptedException {
            printNumbers(false);
        }

        private void printNumbers(boolean odd) throws InterruptedException {
            while (current <= max) {
                while (current <= max && (current % 2 == 1) != odd) {
                    wait();
                }

                if (current <= max) {
                    System.out.println((odd ? "Odd: " : "Even: ") + current++);
                    notifyAll();
                }
            }
        }
    }

    private static final class LockPrinter {
        private final int max;
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition oddTurn = lock.newCondition();
        private final Condition evenTurn = lock.newCondition();
        private int current = 1;

        private LockPrinter(int max) {
            this.max = max;
        }

        private void printOdd() throws InterruptedException {
            printNumbers(true);
        }

        private void printEven() throws InterruptedException {
            printNumbers(false);
        }

        private void printNumbers(boolean odd) throws InterruptedException {
            lock.lockInterruptibly();
            try {
                Condition turn = odd ? oddTurn : evenTurn;
                Condition nextTurn = odd ? evenTurn : oddTurn;

                while (current <= max) {
                    while (current <= max && (current % 2 == 1) != odd) {
                        turn.await();
                    }

                    if (current <= max) {
                        System.out.println((odd ? "Odd: " : "Even: ") + current++);
                        nextTurn.signal();
                    }
                }
            } finally {
                lock.unlock();
            }
        }
    }

    private static final class SemaphorePrinter {
        private final int max;
        private final Semaphore oddTurn = new Semaphore(1);
        private final Semaphore evenTurn = new Semaphore(0);
        private int current = 1;

        private SemaphorePrinter(int max) {
            this.max = max;
        }

        private void printOdd() throws InterruptedException {
            printNumbers(true);
        }

        private void printEven() throws InterruptedException {
            printNumbers(false);
        }

        private void printNumbers(boolean odd) throws InterruptedException {
            Semaphore turn = odd ? oddTurn : evenTurn;
            Semaphore nextTurn = odd ? evenTurn : oddTurn;

            while (true) {
                turn.acquire();
                if (current > max) {
                    nextTurn.release();
                    return;
                }

                System.out.println((odd ? "Odd: " : "Even: ") + current++);
                nextTurn.release();
            }
        }
    }
}
